/**
 * list_supported_chains tool — hardcoded list of supported blockchain networks.
 */
import { z } from 'zod';
export const listSupportedChainsSchema = z.object({});
export function handleListSupportedChains() {
    return `# Supported Chains

| Chain | Slug | Type | Endpoint |
|-------|------|------|----------|
| Ethereum | ethereum | Mainnet | \`https://api.onesource.io/federation/ethereum/graphql\` |
| Base | base | Mainnet (L2) | \`https://api.onesource.io/federation/base/graphql\` |
| Optimism | optimism | Mainnet (L2) | \`https://api.onesource.io/federation/optimism/graphql\` |
| Avalanche | avax | Mainnet | \`https://api.onesource.io/federation/avax/graphql\` |
| Shape | shape | Mainnet (L2) | \`https://api.onesource.io/federation/shape/graphql\` |
| Sepolia | sepolia | Testnet | \`https://api.onesource.io/federation/sepolia/graphql\` |

**Endpoint pattern:** \`https://api.onesource.io/federation/{slug}/graphql\`

**Note:** One API key works across all chains — no per-chain keys needed. Pass it via the \`x-bp-token\` header.`;
}
